import sqlite3
from pathlib import Path


MCP = "jira_checkout_reliability"
TARGET = "CHK-2533"


def _connect(ws):
    db_path = Path(ws).resolve().parent / "system" / MCP / "state.db"
    connection = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    connection.row_factory = sqlite3.Row
    return connection


def check_target_transition(ws):
    connection = _connect(ws)
    try:
        issue = connection.execute(
            "SELECT issue_id, status FROM defect_issues WHERE issue_key = ?",
            (TARGET,),
        ).fetchone()
        if not issue:
            return {"score": 0, "detail": "Target Jira issue is missing."}
        history = connection.execute(
            """
            SELECT from_status, to_status, change_reason
            FROM issue_status_history
            WHERE issue_id = ?
            ORDER BY changed_at, history_id
            """,
            (issue["issue_id"],),
        ).fetchall()
    finally:
        connection.close()

    if issue["status"] != "In Progress":
        return {"score": 0, "detail": f"{TARGET} status is {issue['status']!r}, not 'In Progress'."}
    if len(history) != 1:
        return {"score": 0, "detail": f"Expected exactly one new status-history row, found {len(history)}."}
    row = history[0]
    reason = (row["change_reason"] or "").strip().lower()
    has_telemetry = "telemetry" in reason
    has_started_work = any(
        token in reason for token in ("implementation", "implement", "started", "start", "active")
    )
    has_dependency = "rem-25282" in reason or "datadog" in reason or "alert routing" in reason
    if (row["from_status"], row["to_status"]) != ("Open", "In Progress"):
        return {"score": 0, "detail": "The history row is not an Open-to-In Progress transition."}
    if not (has_telemetry and has_started_work and has_dependency):
        return {
            "score": 0,
            "detail": "The transition reason does not tie the change to the started telemetry implementation dependency.",
        }
    return {"score": 1, "detail": "CHK-2533 is In Progress with one correctly reasoned transition."}


def check_protected_target_fields(ws):
    connection = _connect(ws)
    try:
        row = connection.execute(
            """
            SELECT owner_user_id, owner_label_snapshot, severity, due_date, issue_classification
            FROM defect_issues
            WHERE issue_key = ?
            """,
            (TARGET,),
        ).fetchone()
    finally:
        connection.close()
    expected = ("USR-DANIEL-KIM", "Daniel Kim", "Medium", "2025-10-21", "CONFIRMED")
    actual = tuple(row) if row else None
    if actual != expected:
        return {"score": 0, "detail": f"Protected fields changed: expected {expected!r}, got {actual!r}."}
    return {"score": 1, "detail": "Owner, severity, due date, and classification are unchanged."}


def check_other_saved_population_statuses(ws):
    expected = {
        "CHK-2519": "In Production Validation",
        "CHK-2521": "In Progress",
        "CHK-2521-DUP": "Closed",
        "CHK-2524": "Open",
        "CHK-2527": "In Progress",
        "CHK-2530": "In Progress",
        "CHK-2541": "Open",
    }
    connection = _connect(ws)
    try:
        rows = connection.execute(
            """
            SELECT issue_key, status
            FROM defect_issues
            WHERE project_id = 'JPRJ-CHECKOUT' AND saved_filter_member = 1 AND issue_key <> ?
            """,
            (TARGET,),
        ).fetchall()
    finally:
        connection.close()
    actual = {row["issue_key"]: row["status"] for row in rows}
    if actual != expected:
        return {"score": 0, "detail": f"Non-target saved-population statuses changed: {actual!r}."}
    return {"score": 1, "detail": "All non-target saved-population statuses are unchanged."}
